const BROTHERHOOD_ITEMS: RefCardItem[] = [{"id":"believersBrothers","title":"Believers Are Brothers","category":"unity","refs":["49:10","3:103","8:63"],"desc":"The Quran declares all believers are brothers and commands reconciliation."},{"id":"holdRope","title":"Hold to Allah's Rope Together","category":"unity","refs":["3:103"],"desc":"The Quran commands holding to the rope of Allah all together and not dividing."},{"id":"doNotDivide","title":"Do Not Divide","category":"unity","refs":["3:105","6:159","30:32"],"desc":"The Quran condemns dividing into sects after clear guidance has come."},{"id":"reconcileDispute","title":"Reconcile Those in Dispute","category":"reconciliation","refs":["49:9-10","4:128","2:182"],"desc":"The Quran commands making peace between two disputing groups of believers."},{"id":"makeSettlement","title":"Settlement Is Better","category":"reconciliation","refs":["49:9","4:35","4:128"],"desc":"The Quran favors reconciliation and settlement over prolonged dispute."},{"id":"cooperateGood","title":"Cooperate in Goodness","category":"cooperation","refs":["5:2","9:71","22:77"],"desc":"The Quran commands cooperating in righteousness and taqwa, not in sin."},{"id":"forbidEvil","title":"Forbid Evil Together","category":"cooperation","refs":["3:104","3:110","9:71","22:41"],"desc":"The Quran calls believers to command good and forbid evil together."},{"id":"noEnmity","title":"No Enmity Among Believers","category":"rights","refs":["49:11-12","59:10"],"desc":"The Quran forbids enmity between believers and asks forgiveness for all."},{"id":"community","title":"Best Community","category":"ummah","refs":["3:110","2:143","22:78"],"desc":"The Quran describes the Muslim community as the best brought forth for mankind."}];

