const OATHS_ITEMS: RefCardItem[] = [{"id":"doNotMakeObstacle","title":"Do Not Make Oaths an Obstacle","category":"oaths","refs":["2:224","66:2"],"desc":"The Quran warns against using Allah's name as an excuse to avoid doing good."},{"id":"laghwOath","title":"Unintentional Oaths Overlooked","category":"oaths","refs":["2:225","5:89"],"desc":"The Quran distinguishes unintentional oaths from deliberate ones."},{"id":"oathExpiation","title":"Expiation for Oaths","category":"expiation","refs":["5:89","66:2"],"desc":"The Quran prescribes expiation for breaking a deliberate oath."},{"id":"expiateFeed","title":"Feed Ten Poor People","category":"expiation","refs":["5:89"],"desc":"One form of expiation for oaths is feeding or clothing ten poor people."},{"id":"expiateFasting","title":"Fasting as Expiation","category":"expiation","refs":["5:89","58:4"],"desc":"If unable to do other expiation, fasting three days is prescribed."},{"id":"ila","title":"Ila — Oath of Abstention","category":"ila","refs":["2:226-227"],"desc":"The Quran gives a four-month period for those who take an oath to abstain."},{"id":"zihar","title":"Zihar — Unlawful Comparison","category":"zihar","refs":["58:1-4"],"desc":"The Quran addresses zihar and calls it an evil statement."},{"id":"ziharExpiation","title":"Expiation for Zihar","category":"zihar","refs":["58:3-4"],"desc":"The Quran prescribes freeing a slave, fasting, or feeding the poor for zihar."},{"id":"fulfillVows","title":"Fulfill Vows","category":"vows","refs":["22:29","76:7-9","2:270"],"desc":"The Quran praises those who fulfill their vows and commands fulfilling them."}];

const SIGNS_CATEGORIES: Category[] = [{"id":"cosmos","title":"Sky & Cosmos"},{"id":"earth","title":"Earth & Nature"},{"id":"self","title":"The Human Self"},{"id":"water","title":"Water & Rain"},{"id":"dayNight","title":"Day & Night"},{"id":"stewardship","title":"Stewardship of the Earth"}];
const SIGNS_ITEMS: RefCardItem[] = [{"id":"heavensEarth","title":"Creation of the Heavens and Earth","category":"cosmos","refs":["2:164","3:190-191","10:6","45:3-5"],"desc":"The Quran repeatedly points to the creation of the heavens and earth as clear signs of Allah."},{"id":"dayNightAlternation","title":"Alternation of Day and Night","category":"dayNight","refs":["3:190","10:6","23:80","28:73","36:37-40"],"desc":"The Quran presents the alternation of day and night as a sign for those who reflect."},{"id":"rainLife","title":"Rain Giving Life to the Earth","category":"water","refs":["2:164","6:99","16:65","22:5","35:9","50:9-11"],"desc":"Allah sends down rain and revives the dead earth — a Quranic sign of resurrection and mercy."},{"id":"creationHumans","title":"Creation of the Human Being","category":"self","refs":["23:12-14","32:7-9","36:77","75:37-40","86:5-7"],"desc":"The Quran details human creation from humble origins as a sign of Allah's power."},{"id":"soulBreathed","title":"The Soul and Sleep","category":"self","refs":["15:29","32:9","38:72","39:42"],"desc":"Allah breathes the soul into the human form; sleep is described as a minor death."},{"id":"seasRivers","title":"Seas, Rivers, and Ships","category":"water","refs":["14:32","16:14","35:12","55:19-20"],"desc":"The Quran points to the harnessing of seas and rivers as signs of divine provision."},{"id":"mountainsPegs","title":"Mountains as Pegs","category":"earth","refs":["16:15","21:31","31:10","78:7","88:19"],"desc":"The Quran describes mountains as pegs that stabilise the earth."},{"id":"starsNavigation","title":"Stars as Navigation","category":"cosmos","refs":["6:97","16:16","67:5"],"desc":"The Quran describes stars as guides for those navigating land and sea."},{"id":"animalsSign","title":"Animals as Signs","category":"earth","refs":["16:66","16:68-69","36:71-73"],"desc":"The Quran points to cattle, bees, and animals as signs of Allah's provision and wisdom."},{"id":"windClouds","title":"Wind and Clouds","category":"cosmos","refs":["2:164","7:57","15:22","30:46","35:9"],"desc":"The Quran describes winds as signs — carrying rain, driving ships, and scattering seeds."},{"id":"humanDesignSign","title":"Signs Within Yourselves","category":"self","refs":["41:53","51:20-21","95:4"],"desc":"The Quran declares that signs are within the human being itself, and that humans were created in the finest form."},{"id":"khalifaEarth","title":"Humanity as Stewards of the Earth","category":"stewardship","refs":["2:30","6:165","35:39"],"desc":"The Quran declares that Allah made humanity successors on the earth, entrusted with responsibility over it."},{"id":"doNotCorrupt","title":"Do Not Spread Corruption on Earth","category":"stewardship","refs":["7:56","2:205","30:41"],"desc":"The Quran forbids spreading corruption on the earth after it has been set in order."},{"id":"diversitySign","title":"Diversity of Languages and Colours","category":"self","refs":["30:22","49:13","35:27-28"],"desc":"The Quran presents the diversity of human languages and colors as a sign of Allah for those who have knowledge."}];

const WOMEN_CATEGORIES: Category[] = [{"id":"maryam","title":"Maryam"},{"id":"asiya","title":"Asiya"},{"id":"stories","title":"Women in Quranic Stories"},{"id":"equality","title":"Spiritual Equality"},{"id":"rights","title":"Rights & Honour"},{"id":"ayesha","title":"Ayesha — Cleared by Revelation"}];
const WOMEN_ITEMS: RefCardItem[] = [{"id":"ifkVerses","title":"Ayesha Cleared by Revelation","category":"ayesha","refs":["24:11-20"],"desc":"When Ayesha was falsely accused, Allah revealed verses directly clearing her name — among the clearest Quranic defences of any person."},{"id":"maryamChosen","title":"Maryam — Chosen and Purified","category":"maryam","refs":["3:42-43","3:45-47"],"desc":"The Quran states that Allah chose Maryam, purified her, and preferred her over all women of the worlds."},{"id":"maryamAngel","title":"The Angel Visits Maryam","category":"maryam","refs":["19:16-21"],"desc":"The Quran recounts the angel appearing to Maryam and the news of Isa's birth without a father."},{"id":"maryamBirth","title":"The Birth of Isa","category":"maryam","refs":["19:22-34","21:91","66:12"],"desc":"Maryam gave birth alone, and the Quran describes her patience, the miracle of the palm tree, and Isa speaking from the cradle."},{"id":"maryamSurah","title":"Surah Maryam — The Surah Named After Her","category":"maryam","refs":["19:1-15"],"desc":"Maryam is the only woman named in the Quran and the only woman to have a Surah named after her."},{"id":"asiyaPrayer","title":"Asiya's Prayer — A Model for Believers","category":"asiya","refs":["66:11"],"desc":"The Quran presents Asiya, wife of Pharaoh, as a model: she prayed for a house near Allah in Paradise."},{"id":"queenSheba","title":"The Queen of Sheba","category":"stories","refs":["27:23-44"],"desc":"The Quran recounts the Queen of Sheba's wisdom, her throne, and her submission to Allah."},{"id":"wivesOfProphet","title":"The Choice Given to the Prophet's Wives","category":"ayesha","refs":["33:28-34","66:1-5"],"desc":"The Quran offered the Prophet's wives a choice between this world and Allah — they chose Allah."},{"id":"equalBeliever","title":"Believing Men and Women are Equal Before Allah","category":"equality","refs":["33:35","9:71-72","40:40","4:124"],"desc":"The Quran explicitly lists believing men and women side by side as equal recipients of Allah's reward."},{"id":"mothersHonour","title":"The Honour of Mothers","category":"rights","refs":["31:14-15","46:15","17:23-24","2:233"],"desc":"The Quran commands kindness to parents with special weight given to mothers, who bear hardship upon hardship."},{"id":"womenRights","title":"Women's Rights in the Quran","category":"rights","refs":["2:228","4:19","4:32","65:6-7"],"desc":"The Quran establishes rights for women in marriage, maintenance, inheritance, and personal autonomy."}];

const LINEAGE_CATEGORIES: Category[] = [{"id":"prophetsFamily","title":"Prophets' Families Who Disbelieved"},{"id":"wives","title":"Wives Not Saved by Their Husbands"},{"id":"contrast","title":"Faith Overcomes Origin"},{"id":"principle","title":"The Quranic Principle"}];
const LINEAGE_ITEMS: RefCardItem[] = [{"id":"nuhSon","title":"Nuh's Son — 'He is Not of Your Family'","category":"prophetsFamily","refs":["11:42-47"],"tags":["Nuh","Son","Lineage","Ark"],"desc":"Nuh called his son to board the ark. He refused and drowned. When Nuh pleaded, Allah answered: 'He is not of your family — his deeds were not righteous.' The clearest Quranic statement that lineage means nothing before Allah."},{"id":"ibrahimFather","title":"Ibrahim's Father — The Prophet Could Not Save Him","category":"prophetsFamily","refs":["6:74","9:113-114","19:46-47"],"tags":["Ibrahim","Azar","Father","Idols"],"desc":"Ibrahim's father Azar was an idol-maker. Ibrahim prayed for him with tenderness, but after it became clear his father died in disbelief, Allah commanded Ibrahim to stop — and Ibrahim disassociated. Being the father of the greatest monotheist availed Azar nothing."},{"id":"abuLahab","title":"Abu Lahab — The Prophet's Uncle Condemned by Name","category":"prophetsFamily","refs":["111:1-5"],"tags":["Abu Lahab","Uncle","Prophet","Hellfire"],"desc":"Abu Lahab was the Prophet's own uncle. He is the only person condemned to the Fire by name in the Quran. Surah Al-Masad declares his wealth and children will not avail him — he will enter a fire of blazing flame."},{"id":"nuhWife","title":"The Wife of Nuh — A Warning for Disbelievers","category":"wives","refs":["66:10"],"tags":["Nuh","Wife","Betrayal","Hellfire"],"desc":"The Quran presents the wife of Nuh as one of two examples for disbelievers — she was married to a prophet yet betrayed him. Her closeness to a prophet did not save her. It was said to her: 'Enter the Fire with those who enter.'"},{"id":"lutWife","title":"The Wife of Lut — Left Behind with the Destroyed","category":"wives","refs":["66:10","11:81","7:83"],"tags":["Lut","Wife","Destruction","Punishment"],"desc":"The wife of Lut was told to leave with her husband but was among those destroyed. The Quran pairs her with the wife of Nuh as a deliberate dual example: two women married to prophets, both condemned because of their own choices."},{"id":"abuLahabWife","title":"The Wife of Abu Lahab — She Too Will Enter the Fire","category":"wives","refs":["111:4-5"],"tags":["Abu Lahab","Wife","Thorns","Hellfire"],"desc":"The Quran condemns not only Abu Lahab but his wife alongside him — she carried thorns to harm the Prophet. Being the wife of the Prophet's uncle gave her no protection. She will carry wood as fuel with a rope of twisted fibre around her neck."},{"id":"asiyaContrast","title":"Asiya — Wife of the Worst Man, Yet in Paradise","category":"contrast","refs":["66:11"],"tags":["Asiya","Pharaoh","Faith","Paradise"],"desc":"Asiya was married to Pharaoh — the most tyrannical figure in the Quran who claimed to be god. Yet her own faith made her one of the greatest believers. The Quran deliberately pairs her story with the wives of Nuh and Lut: closeness to the worst did not corrupt her."},{"id":"believingManPharaoh","title":"The Believing Man in Pharaoh's Court","category":"contrast","refs":["40:28-44"],"tags":["Pharaoh","Believer","Faith","Musa"],"desc":"A man from Pharaoh's own family and inner circle hid his faith and spoke up for Musa, reasoning with Pharaoh's people. Living at the centre of the most powerful disbeliever did not prevent him from recognising and protecting the truth."},{"id":"noBearer","title":"No Soul Bears Another's Burden","category":"principle","refs":["6:164","17:15","35:18","53:38"],"tags":["Accountability","Burden","Individual","Justice"],"desc":"The Quran states the principle four times in different surahs: no bearer of burdens bears the burden of another. Every soul is accountable only for what it earned. No prophet, parent, or ancestor can carry the weight of another person's choices."},{"id":"fleeFamily","title":"On That Day — People Will Flee From Their Own Family","category":"principle","refs":["80:34-37","70:10-14"],"tags":["Day of Judgment","Family","Accountability","Flight"],"desc":"The Quran describes a Day so severe that a man will flee from his own brother, mother, father, wife, and children — every person consumed with their own account. On that Day, the only thing that matters is what a person brought for themselves."}];

const BOOK_CATEGORIES: Category[] = [{"id":"names","title":"The Quran's Own Names"},{"id":"purpose","title":"Purpose & Role"},{"id":"revelation","title":"How It Was Revealed"},{"id":"challenge","title":"The Challenge (Tahaddi)"},{"id":"preservation","title":"Preservation"},{"id":"effect","title":"Its Effect on Hearts"}];
const BOOK_ITEMS: RefCardItem[] = [{"id":"alHuda","title":"Al-Huda — The Guidance","category":"names","refs":["2:2","2:185","3:138"],"tags":["Guidance","Al-Huda","Names of Quran"],"desc":"The Quran calls itself Al-Huda — guidance for those who have taqwa and for all mankind. Its primary purpose, stated in its second verse, is to guide."},{"id":"alFurqan","title":"Al-Furqan — The Criterion","category":"names","refs":["25:1","2:185","3:4"],"tags":["Al-Furqan","Criterion","Names of Quran"],"desc":"The Quran calls itself Al-Furqan — the criterion that distinguishes truth from falsehood. Surah Al-Furqan opens: 'Blessed is He who sent down the Criterion upon His servant.'"},{"id":"alNoor","title":"Al-Noor — The Light","category":"names","refs":["4:174","5:15-16","7:157"],"tags":["Al-Noor","Light","Names of Quran"],"desc":"The Quran describes itself as a clear light from Allah that leads people out of darkness into light, by His permission, to the path of the Almighty, the Praiseworthy."},{"id":"alShifa","title":"Al-Shifa — The Healing","category":"names","refs":["17:82","10:57","41:44"],"tags":["Al-Shifa","Healing","Names of Quran"],"desc":"The Quran declares itself a healing for what is in the chests — a mercy for the believers. It heals doubts, diseases of the heart, and spiritual ailments."},{"id":"alDhikr","title":"Al-Dhikr — The Reminder","category":"names","refs":["15:9","16:44","21:50","38:87"],"tags":["Al-Dhikr","Reminder","Names of Quran"],"desc":"The Quran calls itself Al-Dhikr — the Reminder. In the same verse Allah declares: 'And indeed it is We who have sent down the Reminder, and indeed We will be its guardian.'"},{"id":"alMubeen","title":"Al-Kitab Al-Mubeen — The Clear Book","category":"names","refs":["12:1","15:1","26:2","43:2","44:2"],"tags":["Al-Mubeen","Clear Book","Names of Quran"],"desc":"The Quran opens multiple surahs with the declaration: 'By the Clear Book.' Al-Mubeen means clear, manifest, and making clear — both in itself and in what it clarifies for others."},{"id":"alAzeemMajid","title":"Al-Azeem & Al-Majid — The Magnificent, The Glorious","category":"names","refs":["15:87","50:1","85:21-22"],"tags":["Al-Azeem","Al-Majid","Glorious","Names of Quran"],"desc":"Allah describes the Quran as Al-Azeem (Magnificent — 15:87) and Al-Majid (Glorious — 85:21). These are among the greatest titles of honour used for any of Allah's creations."},{"id":"alHakim","title":"Al-Kitab Al-Hakim — The Book of Wisdom","category":"names","refs":["3:58","10:1","31:2","36:2"],"tags":["Al-Hakim","Wisdom","Names of Quran"],"desc":"The Quran is called Al-Hakim — the Wise Book, full of wisdom. Surah Ya-Sin opens: 'By the Quran, full of wisdom.' The wisdom it contains is from Allah, the All-Wise."},{"id":"guidanceForMankind","title":"Guidance for All Mankind","category":"purpose","refs":["2:185","3:4","14:1","39:41"],"tags":["Guidance","Mankind","Purpose"],"desc":"The Quran was sent as guidance for all mankind. Surah Al-Baqarah (2:185) states it was sent as guidance for people, with clear proofs of guidance and the criterion."},{"id":"confirmsPrevious","title":"Confirms and Guards Previous Scriptures","category":"purpose","refs":["2:97","3:3-4","5:48","10:37"],"tags":["Tawrat","Injil","Previous Scriptures","Purpose"],"desc":"The Quran states it confirms the Tawrat and the Injil and stands as a guardian over all previous scriptures. It did not come to replace truth — it came to complete and protect it."},{"id":"warnerGivesGladTidings","title":"Warner and Giver of Glad Tidings","category":"purpose","refs":["17:9","18:1-2","46:12"],"tags":["Warning","Glad Tidings","Purpose"],"desc":"The Quran describes itself as guiding to what is most upright — giving glad tidings to the believers who do good, and warning those who say Allah has taken a son."},{"id":"revealedGradually","title":"Why Revealed Gradually Over 23 Years","category":"revelation","refs":["25:32","17:106","76:23"],"tags":["Revelation","Gradual","Stages"],"desc":"When disbelievers asked why it was not revealed all at once, the Quran answered: 'So that We may strengthen your heart thereby, and We have spaced it distinctly.' It came in stages matched to events."},{"id":"revealedInArabic","title":"Why Revealed in Arabic","category":"revelation","refs":["12:2","41:3","43:3","26:192-195"],"tags":["Arabic","Revelation","Language"],"desc":"The Quran explains it was revealed in clear Arabic so that people may understand and reflect. It is from the Lord of all worlds, brought down by the Trustworthy Spirit upon the Prophet's heart."},{"id":"laylatalQadr","title":"Revealed on Laylat al-Qadr","category":"revelation","refs":["97:1-5","44:3-6","2:185"],"tags":["Laylat al-Qadr","Revelation","Night of Decree"],"desc":"The Quran describes its own night of descent — Laylat al-Qadr (the Night of Decree), better than a thousand months. On that blessed night, the angels and the Spirit descend by Allah's permission."},{"id":"tahaddi","title":"The Tahaddi — Bring One Surah Like It","category":"challenge","refs":["2:23-24","10:38","17:88","52:33-34"],"tags":["Tahaddi","Challenge","Miracle","Inimitability"],"desc":"The Quran issues a standing challenge: call all your witnesses besides Allah and produce one surah like it — if you are truthful. Mankind and jinn together cannot. If you cannot, and you never will, then fear the Fire."},{"id":"protected","title":"Allah Guarantees Its Preservation","category":"preservation","refs":["15:9","41:41-42","56:77-80"],"tags":["Preservation","Protection","Allah's Promise"],"desc":"Allah declares: 'Indeed it is We who sent down the Reminder, and indeed We will be its guardian.' Falsehood cannot approach the Quran from before it or behind it — a revelation from the All-Wise, the Praiseworthy."},{"id":"mountainHumbles","title":"A Mountain Would Humble Itself","category":"effect","refs":["59:21"],"tags":["Effect","Hearts","Mountain"],"desc":"Allah says: had We sent down this Quran on a mountain, you would have seen it humbling itself and splitting apart from fear of Allah. These are examples Allah presents so that people may reflect."},{"id":"skinsHeartsHumble","title":"Skins and Hearts Soften","category":"effect","refs":["39:23"],"tags":["Effect","Hearts","Skins","Remembrance"],"desc":"Allah describes the Quran: 'The skins of those who fear their Lord shiver from it, then their skins and their hearts soften to the remembrance of Allah.' It acts on both the body and the soul."},{"id":"increasesIman","title":"Increases the Believers in Iman","category":"effect","refs":["8:2","9:124","17:82"],"tags":["Effect","Iman","Faith","Believers"],"desc":"The Quran states that when its verses are recited, true believers increase in faith. Surah At-Tawbah asks: 'As for those who believe, it has increased them in faith.'"}];

const SABR_CATEGORIES: Category[] = [{"id":"sabrTypes","title":"Types of Patience"},{"id":"reward","title":"Reward of Patience"},{"id":"shukr","title":"Gratitude (Shukr)"},{"id":"tested","title":"When Tested"},{"id":"prophets","title":"Prophets' Patience"},{"id":"hardship","title":"Grief and Hardship"}];
const SABR_ITEMS: RefCardItem[] = [{"id":"sabrWithPrayer","title":"Seek Help Through Patience and Prayer","category":"sabrTypes","refs":["2:45","2:153","2:177"],"desc":"The Quran commands seeking help through sabr and salah — patience is linked directly to worship."},{"id":"beautifulPatience","title":"Beautiful Patience (Sabrun Jameel)","category":"sabrTypes","refs":["12:18","12:83","70:5"],"desc":"Yaqub demonstrated Sabrun Jameel — a patience that doesn't complain to creation, only to Allah."},{"id":"sabrOnTrials","title":"Patience Under Trials","category":"tested","refs":["2:155-157","3:186","39:10"],"desc":"The Quran promises that those who are patient during loss and hardship receive blessings and mercy from Allah."},{"id":"allahWithPatient","title":"Allah is With the Patient","category":"reward","refs":["2:153","8:46","2:249"],"desc":"The Quran repeatedly declares: 'Verily, Allah is with the patient.'"},{"id":"rewardWithoutAccount","title":"Reward Without Measure","category":"reward","refs":["39:10"],"desc":"The Quran promises that the patient will receive their reward without account or limit."},{"id":"shukrIncrease","title":"If You Are Grateful, I Will Increase You","category":"shukr","refs":["14:7","2:152","39:66"],"desc":"The most famous gratitude verse: Allah promises to increase the one who is grateful and warns of punishment for ingratitude."},{"id":"shukrToParents","title":"Gratitude to Allah and Parents Together","category":"shukr","refs":["31:14","46:15","17:23"],"desc":"The Quran links gratitude to Allah directly with gratitude and kindness to parents."},{"id":"shukrOrKufr","title":"Gratitude or Ingratitude — A Choice","category":"shukr","refs":["76:3","27:40","34:13"],"desc":"The Quran frames shukr as a deliberate choice; ingratitude is framed as a form of rejection."},{"id":"ayyubPatience","title":"Ayyub's Patience in Suffering","category":"prophets","refs":["21:83-84","38:41-44"],"desc":"Ayyub called upon Allah in his suffering without despairing; Allah relieved him and restored him."},{"id":"yaqubPatience","title":"Yaqub's Patience Over Yusuf","category":"prophets","refs":["12:18","12:83-87"],"desc":"Yaqub kept his grief between himself and Allah, demonstrating that sabr is not absence of feeling."},{"id":"nuhPatience","title":"Nuh's Patience Over 950 Years","category":"prophets","refs":["71:5-9","23:23-24","26:105-122"],"desc":"The Quran describes Nuh calling his people for 950 years — the longest recorded act of patient perseverance."},{"id":"doNotWeaken","title":"Do Not Weaken or Grieve","category":"hardship","refs":["3:139","47:35"],"desc":"The Quran commands the believers not to weaken or grieve, for they are the superior ones if they are truly believers."},{"id":"afterDifficultyEase","title":"With Difficulty Comes Ease","category":"hardship","refs":["94:5-6","65:7","2:286"],"desc":"The Quran twice affirms that with every hardship comes ease, and that Allah does not burden a soul beyond its capacity."},{"id":"dontDespairAllah","title":"Do Not Despair of Allah's Comfort","category":"hardship","refs":["93:3-5","12:87","39:53"],"desc":"The Quran assures that Allah has not abandoned the Prophet, and commands believers not to despair of Allah's mercy."},{"id":"complaintToAllah","title":"Turning Grief to Allah Alone","category":"hardship","refs":["12:86","21:83-84"],"desc":"Yaqub said he complained only to Allah about his grief; Ayyub turned to Allah in his suffering rather than despairing."}];

const KNOWLEDGE_CATEGORIES: Category[] = [{"id":"seeking","title":"Seeking Knowledge"},{"id":"hikmah","title":"Wisdom (Hikmah)"},{"id":"pen","title":"The Pen & Writing"},{"id":"scholars","title":"Those Who Know"},{"id":"forbidden","title":"Forbidden: Conjecture"}];
const KNOWLEDGE_ITEMS: RefCardItem[] = [{"id":"iqra","title":"Iqra — The First Revelation","category":"seeking","refs":["96:1-5"],"desc":"The very first words revealed to the Prophet were a command to read, in the name of Allah who taught by the pen."},{"id":"taughtByPen","title":"Allah Taught by the Pen","category":"pen","refs":["96:3-5","68:1","31:27"],"desc":"The Quran establishes that Allah taught what humans did not know — through the pen and through revelation."},{"id":"increaseKnowledge","title":"Dua: My Lord, Increase Me in Knowledge","category":"seeking","refs":["20:114"],"desc":"The Quran records a direct command to ask Allah for increase in knowledge — the only such dua for a personal increase."},{"id":"knowDontKnow","title":"Are Those Who Know Equal to Those Who Don't?","category":"scholars","refs":["39:9","35:28","58:11"],"desc":"The Quran asks rhetorically whether those who know and those who don't are equal — and answers clearly that they are not."},{"id":"fearFromKnowledge","title":"Only Those with Knowledge Truly Fear Allah","category":"scholars","refs":["35:28"],"desc":"The Quran states that among Allah's servants, only those with knowledge (ulema) truly fear Him."},{"id":"askPeopleOfKnowledge","title":"Ask the People of Knowledge","category":"scholars","refs":["16:43","21:7"],"desc":"The Quran commands those who don't know to ask the people of knowledge."},{"id":"wisdomGiven","title":"Wisdom is a Great Gift","category":"hikmah","refs":["2:269","3:48","4:54","12:22","17:39","31:12"],"desc":"The Quran describes Hikmah (wisdom) as a vast good given by Allah to whom He wills."},{"id":"luqmanWisdom","title":"Luqman's Wisdom","category":"hikmah","refs":["31:12-19"],"desc":"The Quran preserves Luqman's wisdom — gratitude to Allah, avoiding shirk, honoring parents, not being arrogant."},{"id":"unseen","title":"The Keys of the Unseen","category":"seeking","refs":["6:59","31:34","27:65"],"desc":"The Quran distinguishes between what humans can know and what only Allah knows — the boundaries of human knowledge."},{"id":"forbiddenConjecture","title":"Following Conjecture is Forbidden","category":"forbidden","refs":["10:36","53:28","6:148","17:36"],"desc":"The Quran warns strongly against following Zann (conjecture) in matters of religion — only verified knowledge is acceptable."},{"id":"writingContract","title":"The Longest Verse: Write Your Contracts","category":"pen","refs":["2:282-283"],"desc":"The Quran's longest single verse commands writing contracts and debts as an act of justice and responsibility."}];

const TAWAKKUL_CATEGORIES: Category[] = [{"id":"meaning","title":"What is Tawakkul"},{"id":"promise","title":"Allah's Promise to the Trusting"},{"id":"prophets","title":"Prophets' Reliance"},{"id":"action","title":"Tawakkul with Action"},{"id":"dua","title":"Duas of Reliance"}];
const TAWAKKUL_ITEMS: RefCardItem[] = [{"id":"allahuWakeel","title":"Allah is Sufficient as Wakeel","category":"promise","refs":["3:173","9:129","39:38"],"desc":"The Quran describes those who say 'Allah is sufficient for us' when threatened — and are rewarded."},{"id":"whoeverTrusts","title":"Whoever Relies on Allah — He is Sufficient","category":"promise","refs":["65:3","4:81","8:61"],"desc":"The most cited Tawakkul verse: whoever puts trust in Allah, He is sufficient for him."},{"id":"birdsExample","title":"Birds Trusting in Allah's Provision","category":"promise","refs":["67:19"],"desc":"The Quran describes birds setting out in the morning trusting in Allah — and returning full."},{"id":"ibrahimFamily","title":"Ibrahim's Reliance Leaving His Family","category":"prophets","refs":["14:37","19:48-49"],"desc":"Ibrahim left his family in a barren valley relying entirely on Allah to provide for them."},{"id":"musaTrustsAllah","title":"Musa's Reliance in Front of Pharaoh","category":"prophets","refs":["10:84-86","26:61-62"],"desc":"Musa declared his reliance on Allah even when cornered between the sea and Pharaoh's army."},{"id":"hudReliance","title":"Hud's Declaration of Reliance","category":"prophets","refs":["11:56"],"desc":"Hud declared: 'I put my trust in Allah, my Lord and your Lord.'"},{"id":"nuhReliance","title":"Nuh's Reliance and Firm Decision","category":"prophets","refs":["10:71"],"desc":"Nuh declared complete reliance on Allah and refused to be shaken by his people."},{"id":"makeDecision","title":"Consult, Decide, Then Trust Allah","category":"action","refs":["3:159"],"desc":"The Quran instructs: consult, decide, then rely on Allah — Tawakkul comes after effort."},{"id":"dontSlacken","title":"Don't Slacken — Trust and Act","category":"action","refs":["47:35","4:104"],"desc":"The Quran forbids weakness or slackening while commanding trust in Allah alongside action."},{"id":"duaOfProphet","title":"The Prophet's Dua of Reliance","category":"dua","refs":["11:88","12:67"],"desc":"Quranic duas of prophets placing all reliance on Allah alone."}];

const JINN_CATEGORIES: Category[] = [{"id":"definition","title":"Jinn Nature"},{"id":"shaytan","title":"Shaytan's Story"},{"id":"enmity","title":"Shaytan as Enemy"},{"id":"deception","title":"Shaytan's Tactics"},{"id":"protection","title":"Seeking Protection"},{"id":"jinnBelievers","title":"Believing Jinn"}];
const JINN_ITEMS: RefCardItem[] = [{"id":"jinnCreatedFire","title":"Jinn Created from Fire","category":"definition","refs":["7:12","15:27","55:15"],"desc":"The Quran states that jinn were created from fire, in contrast to humans created from clay."},{"id":"jinnAndHumans","title":"Jinn and Humans Together","category":"definition","refs":["51:56","6:130","55:33"],"desc":"The Quran addresses jinn and humans together as beings created to worship Allah and held accountable."},{"id":"iblisRefusal","title":"Iblis's Refusal to Prostrate","category":"shaytan","refs":["7:11-13","15:30-33","17:61-63","38:71-76"],"desc":"The Quran recounts that Iblis refused to bow to Adam, citing his own origin from fire as superior."},{"id":"iblisRespite","title":"Iblis Asked for Respite","category":"shaytan","refs":["7:14-15","15:36-38","17:62"],"desc":"The Quran states that Iblis asked Allah for respite until the Day of Resurrection, which was granted."},{"id":"shaytanVow","title":"Shaytan's Vow to Mislead","category":"shaytan","refs":["7:16-17","15:39-40","38:82-83"],"desc":"The Quran records Shaytan's oath to approach humanity from every direction to lead them astray, except Allah's sincere servants."},{"id":"shaytanOpenEnemy","title":"Shaytan is an Open Enemy","category":"enmity","refs":["2:168","2:208","17:53","35:6","36:60"],"desc":"The Quran repeatedly declares Shaytan to be a clear and open enemy to the children of Adam."},{"id":"shaytanNoPower","title":"Shaytan Has No Power Over Sincere Believers","category":"enmity","refs":["15:42","16:99-100","17:65"],"desc":"The Quran states that Shaytan has no authority over those who sincerely believe and trust in Allah."},{"id":"shaytanWhispers","title":"Shaytan Whispers","category":"deception","refs":["7:20","20:120","114:4-5"],"desc":"The Quran describes Shaytan whispering to Adam and Eve in the garden, and whispering into the hearts of people."},{"id":"shaytanBeautifiesEvil","title":"Shaytan Beautifies Evil Deeds","category":"deception","refs":["6:43","8:48","27:24","47:25"],"desc":"The Quran states that Shaytan made evil deeds appear beautiful to those who went astray."},{"id":"seekRefuge","title":"Seek Refuge in Allah","category":"protection","refs":["7:200","16:98","41:36","114:1-6"],"desc":"The Quran commands believers to seek refuge in Allah when prompted by Shaytan, as He is the All-Hearing, All-Knowing."},{"id":"jinnListened","title":"The Jinn Who Listened to the Quran","category":"jinnBelievers","refs":["72:1-2","46:29-32"],"desc":"The Quran recounts that a group of jinn listened to the recitation of the Quran and believed, marveling at its guidance."},{"id":"jinnSubmitted","title":"Jinn Who Submitted","category":"jinnBelievers","refs":["72:14","46:31"],"desc":"The Quran records believing jinn declaring their submission to Allah and calling their people to accept guidance."},{"id":"shaytanJudgmentDay","title":"Shaytan Disowns His Followers on Judgment Day","category":"enmity","refs":["14:22"],"desc":"The Quran records Shaytan addressing his followers on Judgment Day, declaring he had no power over them and disowning them."}];

const ANGELS_CATEGORIES: Category[] = [{"id":"nature","title":"Angels' Nature"},{"id":"created","title":"How Created"},{"id":"named","title":"Named Angels"},{"id":"roles","title":"Their Roles"},{"id":"guardians","title":"Guardians"},{"id":"scribes","title":"Recording Angels"}];
const ANGELS_ITEMS: RefCardItem[] = [{"id":"angelsObeyAllah","title":"Angels Do Not Disobey Allah","category":"nature","refs":["66:6","21:19-20","2:285"],"desc":"The Quran states that angels do not disobey Allah in what He commands them, executing all that they are ordered."},{"id":"angelsWorshipConstantly","title":"Angels Worship Allah Constantly","category":"nature","refs":["7:206","21:19-20","37:165-166"],"desc":"The Quran describes angels standing in rows and glorifying Allah, never growing weary or arrogant."},{"id":"jibreelTrustworthy","title":"Jibreel — the Trustworthy Spirit","category":"named","refs":["2:97-98","16:102","26:193-195","81:19-21"],"desc":"The Quran identifies Jibreel as the faithful spirit who brought down the revelation to the Prophet's heart, possessing great power."},{"id":"mikailMentioned","title":"Mikail — Mentioned by Name","category":"named","refs":["2:98"],"desc":"The Quran mentions Mikail by name alongside Jibreel, stating that whoever is an enemy to these angels is an enemy of Allah."},{"id":"angelsWithRevelation","title":"Angels Descend with the Revelation","category":"roles","refs":["97:1-5","26:193"],"desc":"The Quran states that on the Night of Decree angels and the spirit descend, and that the trustworthy spirit brought down the message."},{"id":"recordingAngels","title":"Recording Angels","category":"scribes","refs":["50:17-18","82:10-12","86:4"],"desc":"The Quran states that two angels record every word a person utters, and that every soul has a guardian over it."},{"id":"angelOfDeath","title":"Angel of Death","category":"roles","refs":["32:11","6:61","47:27"],"desc":"The Quran states that the angel of death appointed over people takes their souls at the decreed time."},{"id":"guardianAngels","title":"Guardian Angels","category":"guardians","refs":["6:61","13:11","50:17-18"],"desc":"The Quran describes angels appointed over people as successors who guard them at Allah's command."},{"id":"angelsAtBadr","title":"Angels at Badr","category":"roles","refs":["3:124-125","8:9-12"],"desc":"The Quran states that Allah reinforced the believers at Badr with thousands of angels and cast terror into the disbelievers' hearts."},{"id":"angelsAtTheHour","title":"Angels at the Hour","category":"roles","refs":["39:68","69:17","89:22"],"desc":"The Quran describes angels bearing the throne of Allah, surrounding it, and the trumpet being blown by the appointed angel."},{"id":"angelsPrayForBelievers","title":"Angels Pray for Believers","category":"guardians","refs":["33:43","40:7-9","42:5"],"desc":"The Quran states that Allah and His angels bestow blessings on the believers, and that the angels bearing the throne ask forgiveness for those who believe."},{"id":"angelsInParadise","title":"Angels in Paradise","category":"guardians","refs":["13:23-24","39:73"],"desc":"The Quran describes angels entering upon the inhabitants of Paradise from every gate, greeting them with peace."}];

const HEART_CATEGORIES: Category[] = [{"id":"states","title":"States of the Heart"},{"id":"sealed","title":"Sealed & Hardened"},{"id":"pure","title":"Pure & Sound Heart"},{"id":"diseases","title":"Heart Diseases"},{"id":"guidance","title":"Guidance Through the Heart"}];
const HEART_ITEMS: RefCardItem[] = [{"id":"soundHeart","title":"The Sound Heart","category":"pure","refs":["26:88-89","50:33","37:84"],"desc":"The Quran states that only one who comes to Allah with a sound, pure heart will benefit on the Day of Resurrection."},{"id":"heartsRemember","title":"Hearts That Remember","category":"states","refs":["13:28","3:191","50:37"],"desc":"The Quran declares that it is in the remembrance of Allah that hearts find tranquility and rest."},{"id":"allahKnowsHearts","title":"Allah Knows What Is in the Hearts","category":"states","refs":["2:235","3:29","5:7"],"desc":"The Quran repeatedly states that Allah knows what is hidden in the hearts and what the chests conceal."},{"id":"sealedHearts","title":"Sealed Hearts","category":"sealed","refs":["2:7","6:46","47:24"],"desc":"The Quran describes Allah sealing the hearts of disbelievers so they cannot understand, as a consequence of their rejection."},{"id":"hardenedHearts","title":"Hardened Hearts","category":"sealed","refs":["2:74","5:13","39:22"],"desc":"The Quran compares hard hearts to stone or harder still, and warns that those whose hearts are hardened are in clear misguidance."},{"id":"heartsVeiled","title":"Hearts Veiled from Truth","category":"sealed","refs":["17:45-46","18:57","41:5"],"desc":"The Quran states that coverings are placed over the hearts of those who reject, preventing them from understanding the Quran."},{"id":"diseaseInHeart","title":"Disease in the Heart","category":"diseases","refs":["2:10","5:52","33:12"],"desc":"The Quran describes hypocrisy and doubt as a disease in the heart, which Allah increases for those who persist in it."},{"id":"tranquilityDescends","title":"Tranquility Descends on the Heart","category":"guidance","refs":["48:4","48:18","9:26"],"desc":"The Quran states that Allah sent down tranquility into the hearts of the believers to increase them in faith."},{"id":"heartsAtMention","title":"Hearts Tremble at the Mention of Allah","category":"pure","refs":["8:2","22:35","39:23"],"desc":"The Quran describes the true believers as those whose hearts tremble when Allah is mentioned and whose faith increases when His verses are recited."},{"id":"fearAndHope","title":"Fear and Hope in the Heart","category":"states","refs":["32:16","39:23"],"desc":"The Quran describes the hearts of the devout as combining fear and longing, causing them to rise from sleep to worship."},{"id":"turningHearts","title":"Turning of Hearts","category":"guidance","refs":["3:8","8:24"],"desc":"The Quran records a prayer asking Allah not to let hearts deviate after guidance, and states that Allah intervenes between a person and their heart."},{"id":"blindHearts","title":"Blind Hearts","category":"sealed","refs":["22:46","47:24"],"desc":"The Quran states that it is not the eyes that are blind but the hearts within the chests, and questions why they do not reflect on the Quran."}];

const DEATH_CATEGORIES: Category[] = [{"id":"certainty","title":"Death is Certain"},{"id":"soul","title":"The Soul"},{"id":"barzakh","title":"The Barzakh"},{"id":"martyrs","title":"Martyrs"},{"id":"preparation","title":"Preparation for Death"},{"id":"return","title":"Return to Allah"}];
const DEATH_ITEMS: RefCardItem[] = [{"id":"everySoulTastesDeath","title":"Every Soul Shall Taste Death","category":"certainty","refs":["3:185","21:35","29:57"],"desc":"The Quran declares that every soul shall taste death, and that every created thing is destined to perish."},{"id":"timeOfDeathFixed","title":"The Time of Death is Fixed","category":"certainty","refs":["6:2","7:34","10:49","16:61"],"desc":"The Quran states that every community and every individual has an appointed term that cannot be advanced or delayed."},{"id":"soulTakenByAngel","title":"The Soul Is Taken by the Angel","category":"soul","refs":["6:61","32:11","39:42","47:27"],"desc":"The Quran states that the angel of death and his appointed angels take souls at the decreed time."},{"id":"sleepMinorDeath","title":"Sleep Is the Minor Death","category":"soul","refs":["39:42"],"desc":"The Quran states that Allah takes souls at the time of death and during sleep, returning those not decreed to die until their appointed term."},{"id":"barzakhBarrier","title":"The Barzakh — A Barrier Until Resurrection","category":"barzakh","refs":["23:99-100","36:51-52"],"desc":"The Quran states that behind the deceased is a barzakh until the day they are resurrected, when the horn is blown and they rise from their resting places."},{"id":"martyrsAlive","title":"Martyrs Are Alive, Not Dead","category":"martyrs","refs":["2:154","3:169-170"],"desc":"The Quran instructs not to say that those killed in Allah's path are dead, for they are alive with their Lord, rejoicing in His bounty."},{"id":"momentOfDeath","title":"The Moment of Death","category":"preparation","refs":["6:93","75:26-30"],"desc":"The Quran describes the soul reaching the collarbone and the gaze fixing upward at the moment of death, when it is too late to repent."},{"id":"returnToAllah","title":"Return to Allah","category":"return","refs":["2:156","2:281","6:60"],"desc":"The Quran teaches that believers say they belong to Allah and to Him they return, and that all will return to Him on the Day of Reckoning."},{"id":"goodEndBadEnd","title":"Good End Versus Bad End","category":"soul","refs":["6:93","16:28","16:32"],"desc":"The Quran contrasts the angels who take the righteous souls in goodness with those who take the souls of wrongdoers while they are in sin."},{"id":"deathCannotBeEscaped","title":"Death Cannot Be Escaped","category":"certainty","refs":["3:154","4:78","62:8"],"desc":"The Quran states that death will overtake you wherever you are, even in lofty towers, and that fleeing from it is futile."},{"id":"stateInGrave","title":"The State in the Grave","category":"barzakh","refs":["40:46"],"desc":"The Quran describes Pharaoh's people being exposed to the Fire morning and evening in the barzakh before the final Hour."},{"id":"givingAccount","title":"Giving Account After Death","category":"return","refs":["39:42","40:11"],"desc":"The Quran describes the disbelievers acknowledging in the afterlife that they have died twice and been given life twice, admitting their sins."}];

const YUSUF_CATEGORIES: Category[] = [{"id":"dream","title":"The Dream"},{"id":"betrayal","title":"The Betrayal"},{"id":"egypt","title":"In Egypt"},{"id":"trial","title":"The Trial"},{"id":"prison","title":"In Prison"},{"id":"rise","title":"The Rise"},{"id":"reunion","title":"The Reunion"},{"id":"lessons","title":"Lessons"}];
const YUSUF_ITEMS: RefCardItem[] = [{"id":"yusufDream","title":"Yusuf's Dream","category":"dream","refs":["12:4-6"],"desc":"The Quran recounts Yusuf seeing eleven stars, the sun, and the moon prostrating to him, which his father Ya'qub interpreted as a sign of prophethood."},{"id":"brothersJealousy","title":"Brothers' Jealousy","category":"betrayal","refs":["12:7-10"],"desc":"The Quran describes how Yusuf's brothers envied him for being more beloved to their father and plotted to remove him."},{"id":"thrownInWell","title":"Thrown in the Well","category":"betrayal","refs":["12:15","12:19-20"],"desc":"The Quran states that Yusuf's brothers threw him in the well, and he was later found and sold for a cheap price by a passing caravan."},{"id":"yusufInEgypt","title":"Yusuf in the House of Al-Aziz","category":"egypt","refs":["12:21-22"],"desc":"The Quran states that the man who bought Yusuf in Egypt treated him well, and Allah established Yusuf and gave him knowledge and wisdom."},{"id":"seductionAccusation","title":"The Seduction and Accusation","category":"trial","refs":["12:23-29"],"desc":"The Quran recounts that the wife of Al-Aziz sought to seduce Yusuf, who refused, and her plot was exposed when his shirt was torn from behind."},{"id":"banquetWomen","title":"The Banquet of the Women","category":"trial","refs":["12:30-35"],"desc":"The Quran describes how women who heard of the incident were invited and, upon seeing Yusuf's beauty, cut their hands in astonishment."},{"id":"yusufPrefersPrison","title":"Yusuf Prefers Prison","category":"prison","refs":["12:33-34"],"desc":"The Quran records Yusuf praying to Allah to prefer prison over yielding to sin, and Allah answered his prayer."},{"id":"dreamsInPrison","title":"Dreams in Prison","category":"prison","refs":["12:36-42"],"desc":"The Quran recounts two companions in prison sharing their dreams with Yusuf, who interpreted them accurately through Allah's knowledge."},{"id":"kingDream","title":"The King's Dream","category":"rise","refs":["12:43-49"],"desc":"The Quran describes the king of Egypt seeing seven fat cows devoured by seven lean ones, which Yusuf alone interpreted as years of plenty followed by drought."},{"id":"yusufExonerated","title":"Yusuf's Exoneration","category":"rise","refs":["12:50-57"],"desc":"The Quran states that the king summoned Yusuf, who refused to leave prison until his innocence was publicly established, which it was."},{"id":"brothersComeEgypt","title":"The Brothers Come to Egypt","category":"reunion","refs":["12:58-62"],"desc":"The Quran recounts the brothers of Yusuf coming to Egypt to seek provisions, not recognizing him as the minister who received them."},{"id":"reunificationProstration","title":"Reunification and Prostration","category":"reunion","refs":["12:99-101"],"desc":"The Quran recounts the fulfillment of Yusuf's childhood dream when his parents and brothers prostrated before him, as he was reunited with his family."},{"id":"bestOfStories","title":"Best of Stories","category":"lessons","refs":["12:3","12:111"],"desc":"The Quran describes the story of Yusuf as the best of stories and states that in the accounts of the prophets there is a lesson for those of understanding."},{"id":"yusufPrayer","title":"Yusuf's Prayer","category":"lessons","refs":["12:101"],"desc":"The Quran records Yusuf's prayer asking Allah to let him die as a Muslim and join the righteous, after being granted kingdom and knowledge."}];

const MUSA_CATEGORIES: Category[] = [{"id":"birth","title":"Birth and Early Life"},{"id":"call","title":"The Divine Call"},{"id":"pharaoh","title":"Confronting Pharaoh"},{"id":"exodus","title":"The Exodus"},{"id":"sinai","title":"At Sinai"},{"id":"baniIsrail","title":"With Bani Isra'il"},{"id":"lessons","title":"Lessons"}];
const MUSA_ITEMS: RefCardItem[] = [{"id":"musaCastInRiver","title":"Musa Cast into the River","category":"birth","refs":["20:38-40","28:7"],"desc":"The Quran recounts that Allah inspired Musa's mother to place him in the river, promising to return him and make him a messenger."},{"id":"musaInPharaohsHouse","title":"Musa in Pharaoh's House","category":"birth","refs":["28:8-9"],"desc":"The Quran states that Pharaoh's household picked up Musa from the river, and Pharaoh's wife urged that they not kill him as he may be of benefit."},{"id":"musaFlees","title":"Musa Flees Egypt","category":"birth","refs":["28:15-21"],"desc":"The Quran recounts that Musa accidentally caused the death of a man in a dispute and fled Egypt after being warned of a plot against him."},{"id":"musaInMadyan","title":"Musa in Madyan — Marriage","category":"birth","refs":["28:22-28"],"desc":"The Quran recounts that Musa helped two women water their flocks in Madyan and later married one of them after completing a term of service."},{"id":"burningBush","title":"The Burning Bush — Call to Prophethood","category":"call","refs":["20:9-24","28:29-35","79:15-19"],"desc":"The Quran describes how Allah called to Musa from the sacred valley at the burning bush and appointed him as a messenger to Pharaoh."},{"id":"staffWhiteHand","title":"The Staff and the White Hand — Signs","category":"call","refs":["7:107-108","20:17-22"],"desc":"The Quran records Allah giving Musa two clear signs: his staff becoming a serpent and his hand emerging radiant white."},{"id":"confrontingPharaoh","title":"Confronting Pharaoh","category":"pharaoh","refs":["7:103-126","20:42-53","26:16-33"],"desc":"The Quran recounts Musa and Harun going to Pharaoh to deliver the message and the contest with the sorcerers, whom Musa's staff defeated."},{"id":"plaguesOnEgypt","title":"Plagues on Egypt","category":"pharaoh","refs":["7:130-136"],"desc":"The Quran states that Allah seized the people of Pharaoh with years of drought and shortage of fruits, and sent plagues as signs, which they still rejected."},{"id":"partingOfSea","title":"Parting of the Sea","category":"exodus","refs":["2:50","20:77-78","26:63-66","44:23-24"],"desc":"The Quran recounts that Allah commanded Musa to strike the sea with his staff, and it parted as dry paths, saving the Israelites while Pharaoh's army drowned."},{"id":"goldenCalf","title":"The Golden Calf","category":"baniIsrail","refs":["2:51-54","7:148-153","20:85-98"],"desc":"The Quran recounts that the Israelites, led astray by al-Samiri, worshipped a golden calf while Musa was away on the mount, angering both Musa and Allah."},{"id":"torahAndTablets","title":"The Torah and the Tablets","category":"sinai","refs":["7:145","7:154","2:53"],"desc":"The Quran states that Allah wrote for Musa on the tablets guidance and detail for all things, and gave the Israelites the Torah as light and guidance."},{"id":"musaAtSinai","title":"Musa at Mount Sinai","category":"sinai","refs":["7:142-145","2:63"],"desc":"The Quran recounts that Allah appointed Musa forty nights at the mount where he received the Torah, while the covenant was taken from Bani Isra'il."},{"id":"requestToSeeAllah","title":"Request to See Allah","category":"sinai","refs":["7:143"],"desc":"The Quran recounts that Musa asked Allah to show Himself, and when Allah's glory was manifested on the mountain it crumbled and Musa fell unconscious."},{"id":"alKhidr","title":"Musa and Al-Khidr","category":"lessons","refs":["18:60-82"],"desc":"The Quran recounts Musa's journey with a man of special knowledge, who performed three acts that Musa questioned but which each had a divine wisdom."}];

const IBRAHIM_CATEGORIES: Category[] = [{"id":"call","title":"The Call to Monotheism"},{"id":"idols","title":"Against Idols"},{"id":"fire","title":"The Fire"},{"id":"migration","title":"Migration and Family"},{"id":"kaaba","title":"Building the Kaaba"},{"id":"sacrifice","title":"The Sacrifice"},{"id":"legacy","title":"His Legacy"}];
const IBRAHIM_ITEMS: RefCardItem[] = [{"id":"ibrahimQuestionsFather","title":"Ibrahim Questions His Father","category":"call","refs":["6:74","19:41-46","26:70-77"],"desc":"The Quran recounts Ibrahim addressing his father with gentleness, asking why he worships what cannot hear, see, or benefit him."},{"id":"debatingStars","title":"Debating the Stars and Heavenly Bodies","category":"call","refs":["6:75-79"],"desc":"The Quran describes Ibrahim examining the stars, moon, and sun, and rejecting each as a god when they set, declaring he turns solely to the Creator."},{"id":"ibrahimSmashesIdols","title":"Ibrahim Smashes the Idols","category":"idols","refs":["21:51-67","37:83-96"],"desc":"The Quran recounts that Ibrahim broke the idols of his people except the largest, then challenged them to ask their idols who had done it."},{"id":"ibrahimCastIntoFire","title":"Ibrahim Cast into the Fire","category":"fire","refs":["21:68-70","37:97-98"],"desc":"The Quran recounts that Ibrahim's people decided to burn him as punishment for smashing their idols and defying their way."},{"id":"fireBecomesCool","title":"The Fire Becomes Cool","category":"fire","refs":["21:69"],"desc":"The Quran states that Allah commanded the fire to be cool and safe for Ibrahim, and their plot against him was foiled."},{"id":"ibrahimMigrates","title":"Ibrahim Migrates","category":"migration","refs":["21:71","29:26"],"desc":"The Quran states that Ibrahim migrated, declaring he was going toward his Lord, and that Lut believed with him and they journeyed together."},{"id":"ibrahimDuaForMecca","title":"Ibrahim's Prayer for Mecca and His Family","category":"migration","refs":["14:35-41"],"desc":"The Quran records Ibrahim's prayer asking Allah to make Mecca a city of peace, provide its people with fruits, and establish prayer among his descendants."},{"id":"buildingKaaba","title":"Building the Kaaba with Isma'il","category":"kaaba","refs":["2:127-128"],"desc":"The Quran states that Ibrahim and Isma'il raised the foundations of the Sacred House, praying that Allah accept it from them and make them submissive."},{"id":"dreamSacrifice","title":"The Dream of the Sacrifice","category":"sacrifice","refs":["37:102-107"],"desc":"The Quran recounts that Ibrahim saw in a dream that he was sacrificing his son, and when both submitted, Allah ransomed the son with a great sacrifice."},{"id":"ibrahimFriendOfAllah","title":"Ibrahim Called the Friend of Allah","category":"legacy","refs":["4:125"],"desc":"The Quran states that Allah took Ibrahim as a close friend, as a result of his complete submission and following the way of monotheism."},{"id":"ibrahimPrayerForProgeny","title":"Ibrahim's Prayer for His Progeny","category":"legacy","refs":["2:128-129","14:35-41"],"desc":"The Quran records Ibrahim praying that a messenger from among his descendants be raised to teach the scripture and wisdom and purify the people."},{"id":"hanif","title":"Hanif — The Pure Monotheist","category":"legacy","refs":["2:135","3:67","6:161","16:120-123"],"desc":"The Quran describes Ibrahim as a hanif, a pure monotheist who was not a polytheist, and calls believers to follow his way."}];

const CAVE_CATEGORIES: Category[] = [{"id":"story","title":"The Story"},{"id":"sleep","title":"The Long Sleep"},{"id":"lessons","title":"Lessons from Al-Kahf"},{"id":"otherStories","title":"Other Al-Kahf Stories"}];
const CAVE_ITEMS: RefCardItem[] = [{"id":"youthsSeekRefuge","title":"The Youths Seek Refuge in the Cave","category":"story","refs":["18:10-12"],"desc":"The Quran recounts that the youths of the cave fled to it and prayed to Allah for mercy and right guidance, and He sealed their hearing for years."},{"id":"sleepOfCave","title":"The Sleep of the Cave","category":"sleep","refs":["18:17-18","18:25-26"],"desc":"The Quran states that the sun passed over them without touching them, they appeared awake but slept, and they remained in the cave for three hundred years plus nine."},{"id":"debateOverNumber","title":"Debate Over Their Number","category":"story","refs":["18:22"],"desc":"The Quran states that people will say the youths were three, or five, or seven, and that the precise count is known only to Allah."},{"id":"theirAwakening","title":"Their Awakening","category":"story","refs":["18:19-21"],"desc":"The Quran recounts the youths awakening not knowing how long they had slept, sending one to buy food, and their story becoming a sign for the people of the city."},{"id":"twoGardenOwners","title":"The Believer and the Disbeliever — Two Garden Owners","category":"otherStories","refs":["18:32-44"],"desc":"The Quran contrasts a man who was given two gardens and became arrogant, denying resurrection, with his believing companion who warned him; the garden was destroyed."},{"id":"dhulQarnayn","title":"The Story of Dhul-Qarnayn","category":"otherStories","refs":["18:83-98"],"desc":"The Quran recounts that Dhul-Qarnayn traveled to the ends of the earth and built a barrier of iron and copper to hold back Gog and Magog."},{"id":"musaAndKhidr","title":"The Story of Musa and Al-Khidr","category":"otherStories","refs":["18:60-82"],"desc":"The Quran recounts Musa seeking a man of special knowledge at the junction of two seas, who performed three acts each carrying divine wisdom Musa could not perceive."},{"id":"doNotSayTomorrow","title":"Do Not Say 'I Will Do This Tomorrow'","category":"lessons","refs":["18:23-24"],"desc":"The Quran instructs not to say of anything 'I will do it tomorrow' without adding 'if Allah wills,' and to remember your Lord when you forget."},{"id":"tawakkulInCave","title":"Tawakkul — Trusting Allah Entirely","category":"lessons","refs":["18:10"],"desc":"The Quran records the prayer of the cave youths asking Allah for mercy and to arrange their affair rightly, showing complete reliance on Him."},{"id":"worldIsAdornment","title":"The World Is Adornment and Fleeting","category":"lessons","refs":["18:45-46"],"desc":"The Quran likens the life of this world to rain that causes vegetation to flourish then wither, while righteous deeds are better in reward with your Lord."},{"id":"knowledgeWithAllah","title":"Allah's Knowledge Is Infinite","category":"lessons","refs":["18:109"],"desc":"The Quran states that if the sea were ink for the words of Allah, it would be exhausted before His words were, even if an equal sea were added."},{"id":"arroganceDestroyedByTime","title":"Arrogance Destroyed by Time","category":"lessons","refs":["18:32-44"],"desc":"The Quran describes how the arrogant garden owner's crops were destroyed overnight, leaving him to say he wished he had not associated anyone with his Lord."}];

const MODESTY_CATEGORIES: Category[] = [{"id":"gaze","title":"The Gaze"},{"id":"dress","title":"Dress and Covering"},{"id":"conduct","title":"Modest Conduct"},{"id":"family","title":"Family Modesty Rules"},{"id":"virtue","title":"Virtue of Modesty"}];
const MODESTY_ITEMS: RefCardItem[] = [{"id":"menLowerGaze","title":"Men Lower Their Gaze","category":"gaze","refs":["24:30"],"desc":"The Quran commands believing men to lower their gaze and guard their chastity, stating this is purer for them."},{"id":"womenLowerGaze","title":"Women Lower Their Gaze","category":"gaze","refs":["24:31"],"desc":"The Quran commands believing women to lower their gaze and guard their chastity, as part of broader modesty requirements."},{"id":"womenDrawCovers","title":"Women Draw Their Covers","category":"dress","refs":["24:31","33:59"],"desc":"The Quran instructs women to draw their head coverings over their chests and that the Prophet's wives and believing women draw their outer garments close around them."},{"id":"jilbabFreeWomen","title":"Outer Garment for Believing Women","category":"dress","refs":["33:59"],"desc":"The Quran instructs the Prophet to tell believing women to draw their outer garments over themselves so they may be recognized and not harmed."},{"id":"khimar","title":"Khimar — Head Covering","category":"dress","refs":["24:31"],"desc":"The Quran instructs believing women to draw their head coverings over their chests and not display their adornment except what is apparent."},{"id":"seekingPermission","title":"Seeking Permission Before Entering","category":"family","refs":["24:27-29","24:58-59"],"desc":"The Quran commands believers not to enter homes other than their own without seeking permission and greeting the occupants."},{"id":"modestWalking","title":"Modest Walking","category":"conduct","refs":["24:31"],"desc":"The Quran instructs women not to strike their feet to draw attention to their hidden adornment."},{"id":"modestyInVoice","title":"Modesty in Voice","category":"conduct","refs":["33:32"],"desc":"The Quran instructs the Prophet's wives not to be soft in speech lest those with diseased hearts be tempted, but to speak with appropriate words."},{"id":"screenAsPrivacy","title":"Screen as a Privacy Barrier","category":"family","refs":["33:53"],"desc":"The Quran instructs believers to ask the Prophet's wives for things from behind a screen, as that is purer for both parties."},{"id":"notDisplayingAdornment","title":"Not Displaying Adornment","category":"dress","refs":["24:31","33:33"],"desc":"The Quran instructs believing women not to display their adornment except to specified close relatives, and instructs the Prophet's wives not to make a display of themselves."},{"id":"garmentOfTaqwa","title":"The Garment of Taqwa","category":"virtue","refs":["7:26"],"desc":"The Quran states that Allah has given garments to cover nakedness and as adornment, but that the garment of God-consciousness is the best."},{"id":"elderlyWomenPermission","title":"Permission for Elderly Women","category":"family","refs":["24:60"],"desc":"The Quran states that elderly women who have passed child-bearing age are not at fault if they lay aside their outer garment without displaying adornment."},{"id":"modestyCombined","title":"Modesty Is Comprehensive","category":"conduct","refs":["24:30","24:31"],"desc":"The Quran addresses both men and women with commands covering the gaze, dress, and conduct together as a complete system of modesty."}];

const ARROGANCE_CATEGORIES: Category[] = [{"id":"definition","title":"What Arrogance Is"},{"id":"examples","title":"Examples in the Quran"},{"id":"consequences","title":"Consequences"},{"id":"cure","title":"Humility as the Cure"},{"id":"walkinEarth","title":"Walking on the Earth"}];
const ARROGANCE_ITEMS: RefCardItem[] = [{"id":"doNotWalkProudly","title":"Do Not Walk Proudly on the Earth","category":"walkinEarth","refs":["17:37","31:18"],"desc":"The Quran commands not to walk on earth with arrogance, for you cannot split the earth nor reach the mountains in height."},{"id":"arrogantNotEnterParadise","title":"The Arrogant Will Not Enter Paradise","category":"consequences","refs":["7:40","40:35","39:72"],"desc":"The Quran states that those who deny Allah's signs and are arrogant will not enter Paradise and will be told to enter the gates of Hell permanently."},{"id":"iblisArrogance","title":"Iblis's Arrogance — First Act of Kibr","category":"examples","refs":["7:12","17:61","38:74-76"],"desc":"The Quran records that Iblis refused to prostrate to Adam, saying he was better because he was created from fire, making him the first to display arrogance."},{"id":"pharaohArrogance","title":"Pharaoh's Arrogance","category":"examples","refs":["28:39","40:56","79:24"],"desc":"The Quran states that Pharaoh and his troops behaved arrogantly without right, and that Pharaoh called out claiming to be his people's highest lord."},{"id":"qaroonArrogance","title":"Qaroon's Arrogance","category":"examples","refs":["28:76-83"],"desc":"The Quran recounts that Qaroon went out to his people in his adornment boasting of his wealth, and was swallowed by the earth as a consequence."},{"id":"peopleOfAd","title":"The People of 'Ad","category":"examples","refs":["41:15","26:130"],"desc":"The Quran recounts that the people of 'Ad said no one was mightier than them in power, then the wind destroyed them because of their arrogance."},{"id":"turningAwayInPride","title":"Turning Away in Pride","category":"definition","refs":["31:7","45:8","4:36"],"desc":"The Quran describes those who hear the signs of Allah and turn away in arrogance as deserving a painful punishment."},{"id":"turningFaceInContempt","title":"Do Not Turn Face from People in Contempt","category":"walkinEarth","refs":["31:18-19"],"desc":"The Quran instructs not to turn your cheek away from people in contempt nor walk in insolence, and to be moderate in walking and lowering the voice."},{"id":"allahDoesNotLoveArrogant","title":"Allah Does Not Love the Arrogant","category":"consequences","refs":["16:23","4:36"],"desc":"The Quran clearly states that Allah does not love those who are arrogant and boastful."},{"id":"walkingHumbly","title":"Walking Humbly on Earth","category":"cure","refs":["25:63"],"desc":"The Quran describes the servants of the Most Merciful as those who walk upon the earth in humility."},{"id":"selfPraiseForbidden","title":"Self-Praise Forbidden","category":"definition","refs":["53:32"],"desc":"The Quran states not to claim purity for oneself, as Allah knows best who is truly righteous."},{"id":"servantsWalkHumbly","title":"The Servants of the Most Merciful Walk Humbly","category":"cure","refs":["25:63"],"desc":"The Quran opens its description of the true servants of Allah with their characteristic of walking on the earth with humility."}];

const BACKBITING_CATEGORIES: Category[] = [{"id":"definition","title":"Definition"},{"id":"warnings","title":"Warnings"},{"id":"slander","title":"Slander and False Accusation"},{"id":"mockery","title":"Mockery"},{"id":"spying","title":"Suspicion and Spying"},{"id":"repentance","title":"Repentance and Reform"}];
const BACKBITING_ITEMS: RefCardItem[] = [{"id":"backbitingFlesh","title":"Backbiting Compared to Eating Flesh","category":"definition","refs":["49:12"],"desc":"The Quran asks whether anyone would like to eat the flesh of his dead brother, using this as an analogy for backbiting to make its gravity clear."},{"id":"avoidSuspicion","title":"Avoid Much Suspicion","category":"spying","refs":["49:12"],"desc":"The Quran instructs believers to avoid much suspicion, as some suspicion is sin, and not to spy on or backbite one another."},{"id":"noSpying","title":"No Spying","category":"spying","refs":["49:12","33:53"],"desc":"The Quran prohibits spying on one another and instructs not to enter private spaces without permission, protecting the privacy of others."},{"id":"doNotMock","title":"Do Not Mock Each Other","category":"mockery","refs":["49:11"],"desc":"The Quran prohibits believers from mocking other people, as those being mocked may be better than those who mock them."},{"id":"doNotCallBadNames","title":"Do Not Call Each Other Bad Names","category":"mockery","refs":["49:11"],"desc":"The Quran instructs believers not to insult each other with offensive nicknames after having accepted faith, calling it wickedness."},{"id":"slanderAgainstAisha","title":"Slander — Warning to Believers","category":"slander","refs":["24:11-15"],"desc":"The Quran addresses those who spread slander against a believing woman, calling it a grave sin and warning that those who spread it face a painful punishment."},{"id":"spreadingIndecency","title":"Those Who Spread Indecency","category":"slander","refs":["24:19"],"desc":"The Quran warns those who love to see indecency spread among the believers that they will have a painful punishment in this world and the hereafter."},{"id":"speakRightly","title":"Speak Rightly or Stay Silent","category":"repentance","refs":["33:70","9:119"],"desc":"The Quran instructs believers to fear Allah and speak rightly so that He may set their deeds right and forgive their sins."},{"id":"accusingChasteWomen","title":"Accusing Chaste Women","category":"slander","refs":["24:4","24:23"],"desc":"The Quran prescribes eighty lashes for those who accuse chaste women without four witnesses, and states that those who accuse chaste believing women are cursed."},{"id":"slandererTaleBearer","title":"The Slanderer Who Goes About Tale-Bearing","category":"warnings","refs":["68:10-11","104:1"],"desc":"The Quran condemns those who go about with malicious gossip and slander, warning of destruction for every scorner and slanderer."},{"id":"seekingPermissionPrivacy","title":"Seeking Permission and Respecting Privacy","category":"spying","refs":["24:27-29"],"desc":"The Quran commands believers not to enter homes other than their own until they have asked permission and greeted the inhabitants."},{"id":"forgiveAndOverlook","title":"Forgive and Overlook","category":"repentance","refs":["24:22"],"desc":"The Quran encourages those of virtue to forgive and overlook rather than retaliate in kind, and asks if they would not love Allah to forgive them."}];

